def scores(Q):
    return {c: f(Q) for c, f in zip(CLASSES, (score_g, score_q, score_W, score_Z, score_t))}


def classify(pt, eta, phi):
    s = scores(quantities(pt, eta, phi))
    return max(CLASSES, key=lambda c: s[c])


